int fixedpoint_d2string(char *dst, size_t dstlen, double dvalue, int fractional_digits) {
    if (fractional_digits < 1 || fractional_digits > 17)
        goto err;
    /* min size of 2 ( due to 0. ) + n fractional_digitits + \0 */
    if ((int)dstlen < (fractional_digits+3))
        goto err;
    if (dvalue == 0) {
        dst[0] = '0';
        dst[1] = '.';
        for (int i = 0; i < fractional_digits; i++) {
            dst[2 + i] = '0';
        }
        dst[fractional_digits+2] = '\0';
        return fractional_digits + 2;
    }
    /* scale and round */
    static double powers_of_ten[] = {1.0, 10.0, 100.0, 1000.0, 10000.0, 100000.0, 1000000.0,
    10000000.0, 100000000.0, 1000000000.0, 10000000000.0, 100000000000.0, 1000000000000.0,
    10000000000000.0, 100000000000000.0, 1000000000000000.0, 10000000000000000.0,
    100000000000000000.0 };
    char canon[24];
    int canon_len = fpconv_dtoa(dvalue, canon);
    double scaled_input = dvalue;
    if (canon_len > 0) {
        if (canon_len < (int)sizeof(canon)) {
            double parsed = dvalue;
            canon[canon_len] = '\0';
            string2d(canon, (size_t)canon_len, &parsed);
            scaled_input = parsed;
        }
    }
    long long svalue = llrint(scaled_input * powers_of_ten[fractional_digits]);
    unsigned long long value;
    long long abs_for_sds;
    /* write sign */
    int negative = 0;
    if (svalue < 0) {
        if (svalue != LLONG_MIN) {
            value = -svalue;
            abs_for_sds = -svalue;
        } else {
            value = ((unsigned long long) LLONG_MAX)+1;
            abs_for_sds = LLONG_MAX;
        }
        if (dstlen < 2)
            goto err;
        negative = 1;
        dst[0] = '-';
        dst++;
        dstlen--;
    } else {
        value = svalue;
        abs_for_sds = svalue;
    }

    static const char digitsd[201] =
        "0001020304050607080910111213141516171819"
        "2021222324252627282930313233343536373839"
        "4041424344454647484950515253545556575859"
        "6061626364656667686970717273747576777879"
        "8081828384858687888990919293949596979899";

    /* Check length using the decimal representation of the scaled integer. */
    sds digitstr = sdsfromlonglong(abs_for_sds);
    uint32_t ndigits = (uint32_t)sdslen(digitstr);
    sdsfree(digitstr);
    if (ndigits >= dstlen) goto err;
    else {
        int integer_digits = ndigits - fractional_digits;
        /* Fractional only check to avoid representing 0.7750 as .7750.
         * This means we need to increment the length and store 0 as the first character.
         */
        if (integer_digits < 1) {
            dst[0] = '0';
            integer_digits = 1;
        }
        dst[integer_digits] = '.';
        int size = integer_digits + 1 + fractional_digits;
        /* fill with 0 if required until fractional_digits */
        for (int i = integer_digits + 1; i < fractional_digits; i++) {
            dst[i] = '0';
        }
        int next = size - 1;
        while (value >= 100) {
            int const i = (value % 100) * 2;
            value /= 100;
            dst[next] = digitsd[i + 1];
            dst[next - 1] = digitsd[i];
            next -= 2;
            /* dot position */
            if (next == integer_digits) {
                next--;
            }
        }

        /* Handle last 1-2 digits. */
        if (value < 10) {
            dst[next] = '0' + (uint32_t) value;
        } else {
            int i = (uint32_t) value * 2;
            dst[next] = digitsd[i + 1];
            dst[next - 1] = digitsd[i];
        }
        /* Null term. */
        dst[size] = '\0';
        return size + negative;
    }
err:
    /* force add Null termination */
    if (dstlen > 0)
        dst[0] = '\0';

